def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    w = len(grid[0])
    for r, row in enumerate(grid):
        for s, ref in enumerate(grid):
            if r == s:
                continue
            # Detect a copied row whose terminal run has been replaced by
            # background. The unchanged prefix must match exactly.
            k = 0
            while k < w and row[k] == ref[k]:
                k += 1
            if k == w or row[k] != bg or any(v == bg for v in ref[k:]):
                continue
            if all(v == bg for v in row[k:]):
                for c in range(k, w):
                    out[r][c] = 1
                break
    return out
