def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    threshold = max(1, int(w * 0.4))
    unique_rows = list(dict.fromkeys(tuple(row) for row in grid))
    for r, row in enumerate(grid):
        candidates = []
        for pattern in unique_rows:
            diffs = [c for c in range(w) if row[c] != pattern[c]]
            if diffs:
                candidates.append((len(diffs), diffs, pattern))
        if not candidates:
            continue
        nearest = min(d for d, _, _ in candidates)
        if nearest > threshold:
            continue
        for distance, diffs, pattern in candidates:
            if distance == nearest and all(row[c] == background and pattern[c] != background for c in diffs):
                for c in diffs:
                    out[r][c] = 1
                break
    return out
